mapper.select:
SELECT ACCEPTANCE_ID, ACCEPTANCE_NUMBER, ACCEPTANCE_AMOUNT, CURRENCY, ISSUE_DATE, MATURITY_DATE, DRAWER, PAYEE, ACCEPTING_BANK, ACCEPTING_BANK_ACCOUNT, MARGIN_AMOUNT, MARGIN_RATE, ACCEPTANCE_STATUS, SUBMIT_TIME, APPROVAL_COMMENT, APPROVAL_TIME, COMPANY_ID, COMPANY_NAME, REMARK, CREATE_BY, CREATE_TIME, UPDATE_TIME FROM TBL_BANK_ACCEPTANCE WHERE DELETE_FLAG = 0
AND ACCEPTANCE_NUMBER LIKE CONCAT('%', #{acceptanceNumber}, '%')
AND ACCEPTANCE_STATUS = #{acceptanceStatus}
AND DRAWER LIKE CONCAT('%', #{drawer}, '%')
AND PAYEE LIKE CONCAT('%', #{payee}, '%')
AND ACCEPTING_BANK LIKE CONCAT('%', #{acceptingBank}, '%')
AND COMPANY_ID = #{companyId}
AND CREATE_TIME >= #{startDate}
AND CREATE_TIME <= #{endDate}
ORDER BY CREATE_TIME DESC

